local FlourPackerMaker = {}
local PRODUCTS = {
    iron_flourpacker = { name = "Železni paker za moko", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni paker za moko za mlinarje." },
    bronze_flourpacker = { name = "Bronast paker za moko", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast paker za moko za mlinarje." },
    silver_flourpacker = { name = "Srebrn paker za moko", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn paker za moko za mlinarje." },
    gilded_flourpacker = { name = "Pozlačen paker za moko", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen paker za moko za mlinarje." },
    jewel_set_flourpacker = { name = "Draguljast paker za moko", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast paker za moko za mlinarje." },
    royal_sovereign_flourpacker = { name = "Kraljevski suveren paker za moko", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren paker za moko z biseri za krono." },
}
local BUILDINGS = {
    flourpacker_workshop = { name = "Flourpacker delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    flourpacker_house = { name = "Flourpacker hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_flourpacker_atelier = { name = "Mojstrski flourpacker atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_flourpacker_palace = { name = "Suverena flourpacker palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
FlourPackerMaker.ironStock=12; FlourPackerMaker.bronzeStock=10; FlourPackerMaker.woodStock=14; FlourPackerMaker.leatherStock=12; FlourPackerMaker.silverStock=8; FlourPackerMaker.goldStock=6; FlourPackerMaker.jewelStock=4; FlourPackerMaker.pearlStock=4
FlourPackerMaker.productStock = {}; FlourPackerMaker.buildings = {}; FlourPackerMaker.maker = nil; FlourPackerMaker.activeMaking = {}; FlourPackerMaker.totalProducts = 0; FlourPackerMaker.dayTimer = 0
function FlourPackerMaker.init() FlourPackerMaker.ironStock=12; FlourPackerMaker.bronzeStock=10; FlourPackerMaker.woodStock=14; FlourPackerMaker.leatherStock=12; FlourPackerMaker.silverStock=8; FlourPackerMaker.goldStock=6; FlourPackerMaker.jewelStock=4; FlourPackerMaker.pearlStock=4; FlourPackerMaker.productStock={}; FlourPackerMaker.buildings={}; FlourPackerMaker.maker=nil; FlourPackerMaker.activeMaking={}; FlourPackerMaker.totalProducts=0; FlourPackerMaker.dayTimer=0; print("[FlourPackerMaker] Royal Flour Packer Maker System initialized (6 products, 4 buildings)") end
function FlourPackerMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; FlourPackerMaker.maker={name=n or ("Pakar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pakar najet: %s (spretnost: %d)",FlourPackerMaker.maker.name,s),"success") end; return true end
function FlourPackerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function FlourPackerMaker.build(id) local ok,e=FlourPackerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(FlourPackerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function FlourPackerMaker.getQualityBonus() local b=0; for _,bd in ipairs(FlourPackerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function FlourPackerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and FlourPackerMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and FlourPackerMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and FlourPackerMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and FlourPackerMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and FlourPackerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and FlourPackerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and FlourPackerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and FlourPackerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #FlourPackerMaker.buildings==0 then return false,"Potrebna pakarska delavnica" end; if not FlourPackerMaker.maker then return false,"Potreben pakar" end; return true end
function FlourPackerMaker.make(pt,qty) qty=qty or 1; local ok,e=FlourPackerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then FlourPackerMaker.ironStock=FlourPackerMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then FlourPackerMaker.bronzeStock=FlourPackerMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then FlourPackerMaker.woodStock=FlourPackerMaker.woodStock-d.woodCost*qty end; if d.leatherCost then FlourPackerMaker.leatherStock=FlourPackerMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then FlourPackerMaker.silverStock=FlourPackerMaker.silverStock-d.silverCost*qty end; if d.goldCost then FlourPackerMaker.goldStock=FlourPackerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then FlourPackerMaker.jewelStock=FlourPackerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then FlourPackerMaker.pearlStock=FlourPackerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if FlourPackerMaker.maker then t=math.max(1,t-math.floor(FlourPackerMaker.maker.skill/13)) end; table.insert(FlourPackerMaker.activeMaking,{id="flourpacker_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function FlourPackerMaker.completeMaking(m) local q=1.0+(FlourPackerMaker.getQualityBonus()/100); if FlourPackerMaker.maker then q=q+(FlourPackerMaker.maker.skill/140) end; q=math.min(2.5,q); FlourPackerMaker.productStock[m.productType]=(FlourPackerMaker.productStock[m.productType] or 0)+m.quantity; FlourPackerMaker.totalProducts=FlourPackerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if FlourPackerMaker.maker then FlourPackerMaker.maker.itemsMade=FlourPackerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then FlourPackerMaker.maker.skill=math.min(100,FlourPackerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Paker izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"flourpacker.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function FlourPackerMaker.update(dt) if not _G.state then return end; FlourPackerMaker.dayTimer=FlourPackerMaker.dayTimer+dt; if FlourPackerMaker.dayTimer>=30 then FlourPackerMaker.dayTimer=0; for i=#FlourPackerMaker.activeMaking,1,-1 do local m=FlourPackerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then FlourPackerMaker.completeMaking(m); table.remove(FlourPackerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(FlourPackerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if FlourPackerMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function FlourPackerMaker.getStats() return {ironStock=FlourPackerMaker.ironStock,bronzeStock=FlourPackerMaker.bronzeStock,woodStock=FlourPackerMaker.woodStock,leatherStock=FlourPackerMaker.leatherStock,silverStock=FlourPackerMaker.silverStock,goldStock=FlourPackerMaker.goldStock,jewelStock=FlourPackerMaker.jewelStock,pearlStock=FlourPackerMaker.pearlStock,productStock=FlourPackerMaker.productStock,numBuildings=#FlourPackerMaker.buildings,hasMaker=FlourPackerMaker.maker~=nil,makerName=FlourPackerMaker.maker and FlourPackerMaker.maker.name or "—",makerSkill=FlourPackerMaker.maker and FlourPackerMaker.maker.skill or 0,activeMaking=#FlourPackerMaker.activeMaking,totalProducts=FlourPackerMaker.totalProducts} end
return FlourPackerMaker
